// Generated by Viscosity: "qs" stored as a struct of arrays (fields y, k).
class __Vsc_qs {
  constructor(cap = 16) { this.length = 0; this.cap = cap; this.y = new Float64Array(cap); this.k = new Float64Array(cap); }
  static of(...v) { const c = new __Vsc_qs(Math.max(16, v.length / 2)); for (let i = 0; i < v.length; i += 2) c.push(v[i + 0], v[i + 1]); return c; }
  push(v0, v1) { const n = this.length; if (n === this.cap) this.grow(); this.y[n] = v0; this.k[n] = v1; return (this.length = n + 1); }
  grow() { const cap = (this.cap *= 2); let t; t = new Float64Array(cap); t.set(this.y); this.y = t; t = new Float64Array(cap); t.set(this.k); this.k = t; }
}
// Generated by Viscosity: "ps" stored as a struct of arrays (fields x).
class __Vsc_ps {
  constructor(cap = 16) { this.length = 0; this.cap = cap; this.x = new Float64Array(cap); }
  static of(...v) { const c = new __Vsc_ps(Math.max(16, v.length / 1)); for (let i = 0; i < v.length; i += 1) c.push(v[i + 0]); return c; }
  push(v0) { const n = this.length; if (n === this.cap) this.grow(); this.x[n] = v0; return (this.length = n + 1); }
  grow() { const cap = (this.cap *= 2); let t; t = new Float64Array(cap); t.set(this.x); this.x = t; }
}
// Generated by Viscosity: "rs" stored as a struct of arrays (fields z).
class __Vsc_rs {
  constructor(cap = 16) { this.length = 0; this.cap = cap; this.z = new Float64Array(cap); }
  static of(...v) { const c = new __Vsc_rs(Math.max(16, v.length / 1)); for (let i = 0; i < v.length; i += 1) c.push(v[i + 0]); return c; }
  push(v0) { const n = this.length; if (n === this.cap) this.grow(); this.z[n] = v0; return (this.length = n + 1); }
  grow() { const cap = (this.cap *= 2); let t; t = new Float64Array(cap); t.set(this.z); this.z = t; }
}
// viscosity: ps=soa, qs=soa, rs=soa
// Accesses to one collection inside a rewritten push, array literal or index
// of another: every rewrite must apply (they used to overlap and fail).
const qs = new __Vsc_qs();
for (let i = 0; i < 100; i++) qs.push(i, (i * 7) % 100);
const ps = new __Vsc_ps();
for (let i = 0; i < qs.length; i++) ps.push(qs.y[i] * 2);
const rs = __Vsc_rs.of(qs.y[0], qs.k[1]);
for (let i = 2; i < 80; i++) rs.push((qs.y[i], i));
let s = 0;
for (let i = 0; i < ps.length; i++) s += ps.x[qs.k[i]] + rs.z[qs.k[i] % rs.length];
for (let i = 0; i < ps.length; i++) ps.x[qs.k[i]] += qs.y[i];
